    private readonly Channel<PaymentEvent> _channel = Channel.CreateBounded<PaymentEvent>(
        new BoundedChannelOptions(capacity: 10_000)
        { FullMode = BoundedChannelFullMode.Wait, SingleWriter = false, SingleReader = false });

